import { readFileSync } from 'fs';
import path from 'path';

// 1. Export the raw schema string for Apollo Server's `typeDefs`
export const typeDefs = readFileSync(
    path.join(__dirname, 'schema.graphql'),
    'utf-8'
);

// 2. Re-export everything generated by Code Generator (types, resolver signatures, etc.)
export * from './generated/gql';
export * from './generated/resolvers-types';